function slugifyUniversityValue(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

function buildSupplementalFaculty(country, programId) {
  const program = universityCatalog.programs[programId];
  const firstInstitution = country.faculties?.[0]?.institution || `Catalogue national ${country.name}`;
  const target = program?.targetFaculties?.[0] || program?.title || "Concours universitaire";
  const city = country.faculties?.[0]?.city || "Capitale";

  return {
    id: `${country.code.toLowerCase()}-supp-${slugifyUniversityValue(programId)}`,
    name: `${firstInstitution} - Parcours admission ${target}`,
    city,
    institution: firstInstitution,
    programs: [programId],
    source: "University Integration - filiere complementaire",
    note: "Filiere ajoutee pour couvrir le programme de concours du pays sans ajouter de nouveau pays."
  };
}

